querydefinitiedocument.graphql_document:
query PubliekeInitiatieven($extra: InitiatiefFilter, $limit: Int = 100, $offset: Int = 0) {
  full_initiatieven_list(
    filter: { and: [ { aanmeldstatussen: { status: { eq: "geaccepteerd" } } }, $extra ] },
    limit: $limit, offset: $offset
  ) {
    id
    weergavenaam
    producten { naam omschrijving type CG_laag website }
    planningen { fase startdatum ready_for_use }
    initiatief_domeinen { weergavenaam }
    initiatief_gemeenten { rol weergavenaam }
  }
}

query PubliekInitiatiefDetail($id: Int!) {
  full_initiatieven_list(
    filter: { and: [ { aanmeldstatussen: { status: { eq: "geaccepteerd" } } }, { id: { eq: $id } } ] },
    limit: 1
  ) {
    id
    weergavenaam
    producten { naam omschrijving type CG_laag pitch website git_repo vervangt_ouder_product }
    planningen { fase startdatum ready_for_use planningsinfo waar_tegenaan_gelopen obstakels verwacht_ready_datum }
    bijdragen { type_bijdrage schaal toelichting }
    initiatief_domeinen { weergavenaam domein { weergavenaam } }
    andere_domeinen { domein }
    initiatief_gemeenten { rol weergavenaam gemeente { weergavenaam gemeentegegevens { naam code } } }
    anders_dan_gemeenten { andersDanGemeente }
    initiatief_api_standaarden { weergavenaam }
    andere_api_standaarden { api_standaard }
    betrokken_organisatie { type }
    initiatief_organisaties {
      rol
      organisatie {
        weergavenaam
        organisatienamen { naam }
        organisatiecontactgegevens { url email telefoonnummer }
        contactpersonen {
          rol
          persoon { weergavenaam persoonnamen { naam } persoonscontactgegevens { email telefoonnummer } }
        }
      }
    }
  }
}
